/// A data stream is not a fixed set of messages, but rather a recommendation to the autopilot software. Individual autopilots may or may not obey the recommended messages.
///
/// MAVLink enum `MAV_DATA_STREAM`. Values are open: an unknown value from a newer autopilot
/// is preserved rather than rejected.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct MavDataStream(pub u32);

impl MavDataStream {
    /// Enable all data streams
    pub const MAV_DATA_STREAM_ALL: Self = Self(0);
    /// Enable IMU_RAW, GPS_RAW, GPS_STATUS packets.
    pub const MAV_DATA_STREAM_RAW_SENSORS: Self = Self(1);
    /// Enable GPS_STATUS, CONTROL_STATUS, AUX_STATUS
    pub const MAV_DATA_STREAM_EXTENDED_STATUS: Self = Self(2);
    /// Enable RC_CHANNELS_SCALED, RC_CHANNELS_RAW, SERVO_OUTPUT_RAW
    pub const MAV_DATA_STREAM_RC_CHANNELS: Self = Self(3);
    /// Enable ATTITUDE_CONTROLLER_OUTPUT, POSITION_CONTROLLER_OUTPUT, NAV_CONTROLLER_OUTPUT.
    pub const MAV_DATA_STREAM_RAW_CONTROLLER: Self = Self(4);
    /// Enable LOCAL_POSITION, GLOBAL_POSITION_INT messages.
    pub const MAV_DATA_STREAM_POSITION: Self = Self(6);
    /// Dependent on the autopilot
    pub const MAV_DATA_STREAM_EXTRA1: Self = Self(10);
    /// Dependent on the autopilot
    pub const MAV_DATA_STREAM_EXTRA2: Self = Self(11);
    /// Dependent on the autopilot
    pub const MAV_DATA_STREAM_EXTRA3: Self = Self(12);
}

