    /// Autopilot supports commanding attitude offboard.
    pub const MAV_PROTOCOL_CAPABILITY_SET_ATTITUDE_TARGET: Self = Self(64);
    /// Autopilot supports commanding position and velocity targets in local NED frame.
    pub const MAV_PROTOCOL_CAPABILITY_SET_POSITION_TARGET_LOCAL_NED: Self = Self(128);
