/// The positioning status, as reported by GPS. This message is intended to display status information about each satellite visible to the receiver. See message GLOBAL_POSITION_INT for the global position estimate. This message can contain information for up to 20 satellites.
///
/// MAVLink message 25 (`GPS_STATUS`), from `common.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GpsStatus {
    /// Number of satellites visible
    pub satellites_visible: u8,
    /// Global satellite ID
    pub satellite_prn: [u8; 20],
    /// 0: Satellite not used, 1: used for localization
    pub satellite_used: [u8; 20],
    /// Elevation (0: right on top of receiver, 90: on the horizon) of satellite
    pub satellite_elevation: [u8; 20],
    /// Direction of satellite, 0: 0 deg, 255: 360 deg.
    pub satellite_azimuth: [u8; 20],
    /// Signal to noise ratio of satellite
    pub satellite_snr: [u8; 20],
}

impl Message for GpsStatus {
    const ID: u32 = 25;
    const NAME: &'static str = "GPS_STATUS";
    const CRC_EXTRA: u8 = 23;
    const MIN_LEN: usize = 101;
    const LEN: usize = 101;

    fn decode(payload: &[u8]) -> Self {
        Self {
            satellites_visible: get_u8(payload, 0),
            satellite_prn: core::array::from_fn(|i| get_u8(payload, 1 + i)),
            satellite_used: core::array::from_fn(|i| get_u8(payload, 21 + i)),
            satellite_elevation: core::array::from_fn(|i| get_u8(payload, 41 + i)),
            satellite_azimuth: core::array::from_fn(|i| get_u8(payload, 61 + i)),
            satellite_snr: core::array::from_fn(|i| get_u8(payload, 81 + i)),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.satellites_visible.to_le_bytes());
        for (i, v) in self.satellite_prn.iter().enumerate() {
            put_bytes(out, 1 + i, &v.to_le_bytes());
        }
        for (i, v) in self.satellite_used.iter().enumerate() {
            put_bytes(out, 21 + i, &v.to_le_bytes());
        }
        for (i, v) in self.satellite_elevation.iter().enumerate() {
            put_bytes(out, 41 + i, &v.to_le_bytes());
        }
        for (i, v) in self.satellite_azimuth.iter().enumerate() {
            put_bytes(out, 61 + i, &v.to_le_bytes());
        }
        for (i, v) in self.satellite_snr.iter().enumerate() {
            put_bytes(out, 81 + i, &v.to_le_bytes());
        }
        Self::LEN
    }
}

