/// The attitude in the aeronautical frame (right-handed, Z-down, X-front, Y-right), expressed as quaternion. Quaternion order is w, x, y, z and a zero rotation would be expressed as (1 0 0 0).
///
/// MAVLink message 61 (`ATTITUDE_QUATERNION_COV`), from `common.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AttitudeQuaternionCov {
    /// Timestamp (UNIX Epoch time or time since system boot). The receiving end can infer timestamp format (since 1.1.1970 or since system boot) by checking for the magnitude of the number.
    pub time_usec: u64,
    /// Quaternion components, w, x, y, z (1 0 0 0 is the null-rotation)
    pub q: [f32; 4],
    /// Roll angular speed
    pub rollspeed: f32,
    /// Pitch angular speed
    pub pitchspeed: f32,
    /// Yaw angular speed
    pub yawspeed: f32,
    /// Row-major representation of a 3x3 attitude covariance matrix (states: roll, pitch, yaw; first three entries are the first ROW, next three entries are the second row, etc.). If unknown, assign NaN value to first element in the array.
    pub covariance: [f32; 9],
}

impl Message for AttitudeQuaternionCov {
    const ID: u32 = 61;
    const NAME: &'static str = "ATTITUDE_QUATERNION_COV";
    const CRC_EXTRA: u8 = 167;
    const MIN_LEN: usize = 72;
    const LEN: usize = 72;

    fn decode(payload: &[u8]) -> Self {
        Self {
            time_usec: get_u64(payload, 0),
            q: core::array::from_fn(|i| get_f32(payload, 8 + i * 4)),
            rollspeed: get_f32(payload, 24),
            pitchspeed: get_f32(payload, 28),
            yawspeed: get_f32(payload, 32),
            covariance: core::array::from_fn(|i| get_f32(payload, 36 + i * 4)),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.time_usec.to_le_bytes());
        for (i, v) in self.q.iter().enumerate() {
            put_bytes(out, 8 + i * 4, &v.to_le_bytes());
        }
        put_bytes(out, 24, &self.rollspeed.to_le_bytes());
        put_bytes(out, 28, &self.pitchspeed.to_le_bytes());
        put_bytes(out, 32, &self.yawspeed.to_le_bytes());
        for (i, v) in self.covariance.iter().enumerate() {
            put_bytes(out, 36 + i * 4, &v.to_le_bytes());
        }
        Self::LEN
    }
}

