/// Distance sensor information for an onboard rangefinder.
///
/// MAVLink message 132 (`DISTANCE_SENSOR`), from `common.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct DistanceSensor {
    /// Timestamp (time since system boot).
    pub time_boot_ms: u32,
    /// Minimum distance the sensor can measure
    pub min_distance: u16,
    /// Maximum distance the sensor can measure
    pub max_distance: u16,
    /// Current distance reading
    pub current_distance: u16,
    /// Type of distance sensor.
    /// Values from [`MavDistanceSensor`].
    pub r#type: u8,
    /// Onboard ID of the sensor
    pub id: u8,
    /// Direction the sensor faces. downward-facing: ROTATION_PITCH_270, upward-facing: ROTATION_PITCH_90, backward-facing: ROTATION_PITCH_180, forward-facing: ROTATION_NONE, left-facing: ROTATION_YAW_90, right-facing: ROTATION_YAW_270
    /// Values from [`MavSensorOrientation`].
    pub orientation: u8,
    /// Measurement variance. Max standard deviation is 6cm. UINT8_MAX if unknown.
    pub covariance: u8,
    /// Horizontal Field of View (angle) where the distance measurement is valid and the field of view is known. Otherwise this is set to 0.
    /// MAVLink2 extension field: zero when absent.
    pub horizontal_fov: f32,
    /// Vertical Field of View (angle) where the distance measurement is valid and the field of view is known. Otherwise this is set to 0.
    /// MAVLink2 extension field: zero when absent.
    pub vertical_fov: f32,
    /// Quaternion of the sensor orientation in vehicle body frame (w, x, y, z order, zero-rotation is 1, 0, 0, 0). Zero-rotation is along the vehicle body x-axis. This field is required if the orientation is set to MAV_SENSOR_ROTATION_CUSTOM. Set it to 0 if invalid."
    /// MAVLink2 extension field: zero when absent.
    pub quaternion: [f32; 4],
    /// Signal quality of the sensor. Specific to each sensor type, representing the relation of the signal strength with the target reflectivity, distance, size or aspect, but normalised as a percentage. 0 = unknown/unset signal quality, 1 = invalid signal, 100 = perfect signal.
    /// MAVLink2 extension field: zero when absent.
    pub signal_quality: u8,
}

impl Message for DistanceSensor {
    const ID: u32 = 132;
    const NAME: &'static str = "DISTANCE_SENSOR";
    const CRC_EXTRA: u8 = 85;
    const MIN_LEN: usize = 14;
    const LEN: usize = 39;

    fn decode(payload: &[u8]) -> Self {
        Self {
            time_boot_ms: get_u32(payload, 0),
            min_distance: get_u16(payload, 4),
            max_distance: get_u16(payload, 6),
            current_distance: get_u16(payload, 8),
            r#type: get_u8(payload, 10),
            id: get_u8(payload, 11),
            orientation: get_u8(payload, 12),
            covariance: get_u8(payload, 13),
            horizontal_fov: get_f32(payload, 14),
            vertical_fov: get_f32(payload, 18),
            quaternion: core::array::from_fn(|i| get_f32(payload, 22 + i * 4)),
            signal_quality: get_u8(payload, 38),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.time_boot_ms.to_le_bytes());
        put_bytes(out, 4, &self.min_distance.to_le_bytes());
        put_bytes(out, 6, &self.max_distance.to_le_bytes());
        put_bytes(out, 8, &self.current_distance.to_le_bytes());
        put_bytes(out, 10, &self.r#type.to_le_bytes());
        put_bytes(out, 11, &self.id.to_le_bytes());
        put_bytes(out, 12, &self.orientation.to_le_bytes());
        put_bytes(out, 13, &self.covariance.to_le_bytes());
        put_bytes(out, 14, &self.horizontal_fov.to_le_bytes());
        put_bytes(out, 18, &self.vertical_fov.to_le_bytes());
        for (i, v) in self.quaternion.iter().enumerate() {
            put_bytes(out, 22 + i * 4, &v.to_le_bytes());
        }
        put_bytes(out, 38, &self.signal_quality.to_le_bytes());
        Self::LEN
    }
}

