/// The autopilot is requesting a resource (file, binary, other type of data)
///
/// MAVLink message 142 (`RESOURCE_REQUEST`), from `common.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ResourceRequest {
    /// Request ID. This ID should be reused when sending back URI contents
    pub request_id: u8,
    /// The type of requested URI. 0 = a file via URL. 1 = a UAVCAN binary
    pub uri_type: u8,
    /// The requested unique resource identifier (URI). It is not necessarily a straight domain name (depends on the URI type enum)
    pub uri: [u8; 120],
    /// The way the autopilot wants to receive the URI. 0 = MAVLink FTP. 1 = binary stream.
    pub transfer_type: u8,
    /// The storage path the autopilot wants the URI to be stored in. Will only be valid if the transfer_type has a storage associated (e.g. MAVLink FTP).
    pub storage: [u8; 120],
}

impl Message for ResourceRequest {
    const ID: u32 = 142;
    const NAME: &'static str = "RESOURCE_REQUEST";
    const CRC_EXTRA: u8 = 72;
    const MIN_LEN: usize = 243;
    const LEN: usize = 243;

    fn decode(payload: &[u8]) -> Self {
        Self {
            request_id: get_u8(payload, 0),
            uri_type: get_u8(payload, 1),
            uri: core::array::from_fn(|i| get_u8(payload, 2 + i)),
            transfer_type: get_u8(payload, 122),
            storage: core::array::from_fn(|i| get_u8(payload, 123 + i)),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.request_id.to_le_bytes());
        put_bytes(out, 1, &self.uri_type.to_le_bytes());
        for (i, v) in self.uri.iter().enumerate() {
            put_bytes(out, 2 + i, &v.to_le_bytes());
        }
        put_bytes(out, 122, &self.transfer_type.to_le_bytes());
        for (i, v) in self.storage.iter().enumerate() {
            put_bytes(out, 123 + i, &v.to_le_bytes());
        }
        Self::LEN
    }
}

