/// Data packet, size 16.
///
/// MAVLink message 169 (`DATA16`), from `ardupilotmega.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Data16 {
    /// Data type.
    pub r#type: u8,
    /// Data length.
    pub len: u8,
    /// Raw data.
    pub data: [u8; 16],
}

impl Message for Data16 {
    const ID: u32 = 169;
    const NAME: &'static str = "DATA16";
    const CRC_EXTRA: u8 = 234;
    const MIN_LEN: usize = 18;
    const LEN: usize = 18;

    fn decode(payload: &[u8]) -> Self {
        Self {
            r#type: get_u8(payload, 0),
            len: get_u8(payload, 1),
            data: core::array::from_fn(|i| get_u8(payload, 2 + i)),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.r#type.to_le_bytes());
        put_bytes(out, 1, &self.len.to_le_bytes());
        for (i, v) in self.data.iter().enumerate() {
            put_bytes(out, 2 + i, &v.to_le_bytes());
        }
        Self::LEN
    }
}

