/// Complete set of calibration parameters for the radio
///
/// MAVLink message 221 (`RADIO_CALIBRATION`), from `ualberta.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RadioCalibration {
    /// Aileron setpoints: left, center, right
    pub aileron: [u16; 3],
    /// Elevator setpoints: nose down, center, nose up
    pub elevator: [u16; 3],
    /// Rudder setpoints: nose left, center, nose right
    pub rudder: [u16; 3],
    /// Tail gyro mode/gain setpoints: heading hold, rate mode
    pub gyro: [u16; 2],
    /// Pitch curve setpoints (every 25%)
    pub pitch: [u16; 5],
    /// Throttle curve setpoints (every 25%)
    pub throttle: [u16; 5],
}

impl Message for RadioCalibration {
    const ID: u32 = 221;
    const NAME: &'static str = "RADIO_CALIBRATION";
    const CRC_EXTRA: u8 = 71;
    const MIN_LEN: usize = 42;
    const LEN: usize = 42;

    fn decode(payload: &[u8]) -> Self {
        Self {
            aileron: core::array::from_fn(|i| get_u16(payload, i * 2)),
            elevator: core::array::from_fn(|i| get_u16(payload, 6 + i * 2)),
            rudder: core::array::from_fn(|i| get_u16(payload, 12 + i * 2)),
            gyro: core::array::from_fn(|i| get_u16(payload, 18 + i * 2)),
            pitch: core::array::from_fn(|i| get_u16(payload, 22 + i * 2)),
            throttle: core::array::from_fn(|i| get_u16(payload, 32 + i * 2)),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        for (i, v) in self.aileron.iter().enumerate() {
            put_bytes(out, i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.elevator.iter().enumerate() {
            put_bytes(out, 6 + i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.rudder.iter().enumerate() {
            put_bytes(out, 12 + i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.gyro.iter().enumerate() {
            put_bytes(out, 18 + i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.pitch.iter().enumerate() {
            put_bytes(out, 22 + i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.throttle.iter().enumerate() {
            put_bytes(out, 32 + i * 2, &v.to_le_bytes());
        }
        Self::LEN
    }
}

