    const LEN: usize = 38;

    fn decode(payload: &[u8]) -> Self {
        Self {
            icao_address: get_u32(payload, 0),
            lat: get_i32(payload, 4),
            lon: get_i32(payload, 8),
            altitude: get_i32(payload, 12),
            heading: get_u16(payload, 16),
            hor_velocity: get_u16(payload, 18),
            ver_velocity: get_i16(payload, 20),
            flags: get_u16(payload, 22),
            squawk: get_u16(payload, 24),
            altitude_type: get_u8(payload, 26),
            callsign: core::array::from_fn(|i| get_u8(payload, 27 + i)),
            emitter_type: get_u8(payload, 36),
            tslc: get_u8(payload, 37),
        }
    }

