/// Extended state information for ASLUAVs
///
/// MAVLink message 8006 (`ASLUAV_STATUS`), from `ASLUAV.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AsluavStatus {
    /// Motor RPM
    pub motor_rpm: f32,
    /// Status of the position-indicator LEDs
    pub led_status: u8,
    /// Status of the IRIDIUM satellite communication system
    pub satcom_status: u8,
    /// Status vector for up to 8 servos
    pub servo_status: [u8; 8],
}

impl Message for AsluavStatus {
    const ID: u32 = 8006;
    const NAME: &'static str = "ASLUAV_STATUS";
    const CRC_EXTRA: u8 = 97;
    const MIN_LEN: usize = 14;
    const LEN: usize = 14;

    fn decode(payload: &[u8]) -> Self {
        Self {
            motor_rpm: get_f32(payload, 0),
            led_status: get_u8(payload, 4),
            satcom_status: get_u8(payload, 5),
            servo_status: core::array::from_fn(|i| get_u8(payload, 6 + i)),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.motor_rpm.to_le_bytes());
        put_bytes(out, 4, &self.led_status.to_le_bytes());
        put_bytes(out, 5, &self.satcom_status.to_le_bytes());
        for (i, v) in self.servo_status.iter().enumerate() {
            put_bytes(out, 6 + i, &v.to_le_bytes());
        }
        Self::LEN
    }
}

