/// Cumulative distance traveled for each reported wheel.
///
/// MAVLink message 9000 (`WHEEL_DISTANCE`), from `common.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct WheelDistance {
    /// Timestamp (synced to UNIX time or since system boot).
    pub time_usec: u64,
    /// Distance reported by individual wheel encoders. Forward rotations increase values, reverse rotations decrease them. Not all wheels will necessarily have wheel encoders; the mapping of encoders to wheel positions must be agreed/understood by the endpoints.
    pub distance: [f64; 16],
    /// Number of wheels reported.
    pub count: u8,
}

impl Message for WheelDistance {
    const ID: u32 = 9000;
    const NAME: &'static str = "WHEEL_DISTANCE";
    const CRC_EXTRA: u8 = 113;
    const MIN_LEN: usize = 137;
    const LEN: usize = 137;

    fn decode(payload: &[u8]) -> Self {
        Self {
            time_usec: get_u64(payload, 0),
            distance: core::array::from_fn(|i| get_f64(payload, 8 + i * 8)),
            count: get_u8(payload, 136),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.time_usec.to_le_bytes());
        for (i, v) in self.distance.iter().enumerate() {
            put_bytes(out, 8 + i * 8, &v.to_le_bytes());
        }
        put_bytes(out, 136, &self.count.to_le_bytes());
        Self::LEN
    }
}

