/// Control message with all data sent in UCP control message.
///
/// MAVLink message 10007 (`UAVIONIX_ADSB_OUT_CONTROL`), from `uAvionix.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct UavionixAdsbOutControl {
    /// Barometric pressure altitude (MSL) relative to a standard atmosphere of 1013.2 mBar and NOT bar corrected altitude (m * 1E-3). (up +ve). If unknown set to INT32_MAX
    pub baroaltmsl: i32,
    /// Mode A code (typically 1200 \[0x04B0\] for VFR)
    pub squawk: u16,
    /// ADS-B transponder control state flags
    /// Values from [`UavionixAdsbOutControlState`].
    pub state: u8,
    /// Emergency status
    /// Values from [`UavionixAdsbEmergencyStatus`].
    pub emergencystatus: u8,
    /// Flight Identification: 8 ASCII characters, '0' through '9', 'A' through 'Z' or space. Spaces (0x20) used as a trailing pad character, or when call sign is unavailable.
    pub flight_id: [u8; 8],
    /// X-Bit enable (military transponders only)
    /// Values from [`UavionixAdsbXbit`].
    pub x_bit: u8,
}

impl Message for UavionixAdsbOutControl {
    const ID: u32 = 10007;
    const NAME: &'static str = "UAVIONIX_ADSB_OUT_CONTROL";
    const CRC_EXTRA: u8 = 71;
    const MIN_LEN: usize = 17;
    const LEN: usize = 17;

    fn decode(payload: &[u8]) -> Self {
        Self {
            baroaltmsl: get_i32(payload, 0),
            squawk: get_u16(payload, 4),
            state: get_u8(payload, 6),
            emergencystatus: get_u8(payload, 7),
            flight_id: core::array::from_fn(|i| get_u8(payload, 8 + i)),
            x_bit: get_u8(payload, 16),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.baroaltmsl.to_le_bytes());
        put_bytes(out, 4, &self.squawk.to_le_bytes());
        put_bytes(out, 6, &self.state.to_le_bytes());
        put_bytes(out, 7, &self.emergencystatus.to_le_bytes());
        for (i, v) in self.flight_id.iter().enumerate() {
            put_bytes(out, 8 + i, &v.to_le_bytes());
        }
        put_bytes(out, 16, &self.x_bit.to_le_bytes());
        Self::LEN
    }
}

