///
/// MAVLink message 11005 (`SECURE_COMMAND_REPLY`), from `ardupilotmega.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SecureCommandReply {
    /// Sequence ID from request.
    pub sequence: u32,
    /// Operation that was requested.
    /// Values from [`SecureCommandOp`].
    pub operation: u32,
    /// Result of command.
    /// Values from [`MavResult`].
    pub result: u8,
    /// Data length.
    pub data_length: u8,
    /// Reply data.
    pub data: [u8; 220],
}

impl Message for SecureCommandReply {
    const ID: u32 = 11005;
    const NAME: &'static str = "SECURE_COMMAND_REPLY";
    const CRC_EXTRA: u8 = 93;
    const MIN_LEN: usize = 230;
    const LEN: usize = 230;

    fn decode(payload: &[u8]) -> Self {
        Self {
            sequence: get_u32(payload, 0),
            operation: get_u32(payload, 4),
            result: get_u8(payload, 8),
            data_length: get_u8(payload, 9),
            data: core::array::from_fn(|i| get_u8(payload, 10 + i)),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.sequence.to_le_bytes());
        put_bytes(out, 4, &self.operation.to_le_bytes());
        put_bytes(out, 8, &self.result.to_le_bytes());
        put_bytes(out, 9, &self.data_length.to_le_bytes());
        for (i, v) in self.data.iter().enumerate() {
            put_bytes(out, 10 + i, &v.to_le_bytes());
        }
        Self::LEN
    }
}

/// Adaptive Controller tuning information.
///
/// MAVLink message 11010 (`ADAP_TUNING`), from `ardupilotmega.xml`.
