/// ESC Telemetry Data for ESCs 1 to 4, matching data sent by BLHeli ESCs.
///
/// MAVLink message 11030 (`ESC_TELEMETRY_1_TO_4`), from `ardupilotmega.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct EscTelemetry1To4 {
    /// Voltage.
    pub voltage: [u16; 4],
    /// Current.
    pub current: [u16; 4],
    /// Total current.
    pub totalcurrent: [u16; 4],
    /// RPM (eRPM).
    pub rpm: [u16; 4],
    /// count of telemetry packets received (wraps at 65535).
    pub count: [u16; 4],
    /// Temperature.
    pub temperature: [u8; 4],
}

impl Message for EscTelemetry1To4 {
    const ID: u32 = 11030;
    const NAME: &'static str = "ESC_TELEMETRY_1_TO_4";
    const CRC_EXTRA: u8 = 144;
    const MIN_LEN: usize = 44;
    const LEN: usize = 44;

    fn decode(payload: &[u8]) -> Self {
        Self {
            voltage: core::array::from_fn(|i| get_u16(payload, i * 2)),
            current: core::array::from_fn(|i| get_u16(payload, 8 + i * 2)),
            totalcurrent: core::array::from_fn(|i| get_u16(payload, 16 + i * 2)),
            rpm: core::array::from_fn(|i| get_u16(payload, 24 + i * 2)),
            count: core::array::from_fn(|i| get_u16(payload, 32 + i * 2)),
            temperature: core::array::from_fn(|i| get_u8(payload, 40 + i)),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        for (i, v) in self.voltage.iter().enumerate() {
            put_bytes(out, i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.current.iter().enumerate() {
            put_bytes(out, 8 + i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.totalcurrent.iter().enumerate() {
            put_bytes(out, 16 + i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.rpm.iter().enumerate() {
            put_bytes(out, 24 + i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.count.iter().enumerate() {
            put_bytes(out, 32 + i * 2, &v.to_le_bytes());
        }
        for (i, v) in self.temperature.iter().enumerate() {
            put_bytes(out, 40 + i, &v.to_le_bytes());
        }
        Self::LEN
    }
}

