/// Configure an OSD parameter slot.
///
/// MAVLink message 11033 (`OSD_PARAM_CONFIG`), from `ardupilotmega.xml`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct OsdParamConfig {
    /// Request ID - copied to reply.
    pub request_id: u32,
    /// OSD parameter minimum value.
    pub min_value: f32,
    /// OSD parameter maximum value.
    pub max_value: f32,
    /// OSD parameter increment.
    pub increment: f32,
    /// System ID.
    pub target_system: u8,
    /// Component ID.
    pub target_component: u8,
    /// OSD parameter screen index.
    pub osd_screen: u8,
    /// OSD parameter display index.
    pub osd_index: u8,
    /// Onboard parameter id, terminated by NULL if the length is less than 16 human-readable chars and WITHOUT null termination (NULL) byte if the length is exactly 16 chars - applications have to provide 16+1 bytes storage if the ID is stored as string
    pub param_id: [u8; 16],
    /// Config type.
    /// Values from [`OsdParamConfigType`].
    pub config_type: u8,
}

impl Message for OsdParamConfig {
    const ID: u32 = 11033;
    const NAME: &'static str = "OSD_PARAM_CONFIG";
    const CRC_EXTRA: u8 = 195;
    const MIN_LEN: usize = 37;
    const LEN: usize = 37;

    fn decode(payload: &[u8]) -> Self {
        Self {
            request_id: get_u32(payload, 0),
            min_value: get_f32(payload, 4),
            max_value: get_f32(payload, 8),
            increment: get_f32(payload, 12),
            target_system: get_u8(payload, 16),
            target_component: get_u8(payload, 17),
            osd_screen: get_u8(payload, 18),
            osd_index: get_u8(payload, 19),
            param_id: core::array::from_fn(|i| get_u8(payload, 20 + i)),
            config_type: get_u8(payload, 36),
        }
    }

    fn encode(&self, out: &mut [u8]) -> usize {
        put_bytes(out, 0, &self.request_id.to_le_bytes());
        put_bytes(out, 4, &self.min_value.to_le_bytes());
        put_bytes(out, 8, &self.max_value.to_le_bytes());
        put_bytes(out, 12, &self.increment.to_le_bytes());
        put_bytes(out, 16, &self.target_system.to_le_bytes());
        put_bytes(out, 17, &self.target_component.to_le_bytes());
        put_bytes(out, 18, &self.osd_screen.to_le_bytes());
        put_bytes(out, 19, &self.osd_index.to_le_bytes());
        for (i, v) in self.param_id.iter().enumerate() {
            put_bytes(out, 20 + i, &v.to_le_bytes());
        }
        put_bytes(out, 36, &self.config_type.to_le_bytes());
        Self::LEN
    }
}

